package com.example.minicommerce.order;import static org.assertj.core.api.Assertions.*;import com.example.minicommerce.catalog.infrastructure.*;import com.example.minicommerce.identity.domain.UserRole;import com.example.minicommerce.identity.infrastructure.*;import com.example.minicommerce.inventory.infrastructure.*;import com.example.minicommerce.messaging.infrastructure.OutboxEventRepository;import com.example.minicommerce.order.api.OrderDtos.*;import com.example.minicommerce.order.application.CreateOrderService;import com.example.minicommerce.order.infrastructure.*;import com.example.minicommerce.shared.error.BusinessException;import com.example.minicommerce.support.AbstractPostgresIT;import java.math.BigDecimal;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;class CreateOrderIT extends AbstractPostgresIT{@Autowired UserRepository users;@Autowired ProductRepository products;@Autowired InventoryRepository inventory;@Autowired CreateOrderService service;@Autowired OrderRepository orders;@Autowired IdempotencyRecordRepository idempotency;@Autowired OutboxEventRepository outbox;Long userId;Long productId;@BeforeEach void data(){UserEntity u=users.save(new UserEntity(UUID.randomUUID()+"@example.com","buyer","hash",UserRole.USER));ProductEntity p=new ProductEntity("SKU-"+UUID.randomUUID(),"快照商品","test",new BigDecimal("8000.00"),"JPY");p.publish();p=products.saveAndFlush(p);inventory.saveAndFlush(new InventoryEntity(p.getId(),2));userId=u.getId();productId=p.getId();}@Test void create_writesOrderInventoryIdempotencyAndOutbox(){var result=service.create(userId,"key-"+UUID.randomUUID(),new CreateOrderRequest(List.of(new OrderLineRequest(productId,2)),null));assertThat(result.totalAmount()).isEqualByComparingTo("16000.00");assertThat(result.items().getFirst().productName()).isEqualTo("快照商品");assertThat(inventory.findById(productId).orElseThrow().getReserved()).isEqualTo(2);assertThat(idempotency.count()).isPositive();assertThat(outbox.count()).isPositive();}@Test void insufficientStock_rollsBackEveryWrite(){long beforeOrders=orders.count(),beforeIdem=idempotency.count(),beforeOutbox=outbox.count();assertThatThrownBy(()->service.create(userId,"key-"+UUID.randomUUID(),new CreateOrderRequest(List.of(new OrderLineRequest(productId,3)),null))).isInstanceOf(BusinessException.class);assertThat(orders.count()).isEqualTo(beforeOrders);assertThat(idempotency.count()).isEqualTo(beforeIdem);assertThat(outbox.count()).isEqualTo(beforeOutbox);assertThat(inventory.findById(productId).orElseThrow().getAvailable()).isEqualTo(2);}}
